// No require('fs') — same fix as the other two flows, see their
// equivalent nodes for the full explanation (Function nodes are
// sandboxed and have never exposed require()).
let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=bodycomp_import,status=started value=1 ' + nowNs;
return msg;

// `ls` with no matches writes to stderr and exits non-zero — stdout
// (this node's output 1, wired here) is simply empty in that case,
// which is the normal/expected "nothing new to import" outcome, not
// a failure.
const files = (msg.payload || '').split('\n').map(s => s.trim()).filter(Boolean);
if (!files.length) {
    return [null, msg];
}
msg.files = files;
msg.file_index = 0;
msg.all_rows = [];
return [msg, null];

if (msg.file_index >= msg.files.length) {
    // All files read into msg.all_rows — move on to the merge rules.
    return [null, msg];
}
msg.params = { source: msg.files[msg.file_index] };
delete msg._doc; // never carry a stale workbook object into a fresh read
return [msg, null];

// A1:Q covers the confirmed 17-column layout (PLAN.md §14's table,
// same column order already proven correct for the 'A1:Q41' test
// range). Row count isn't known ahead of time for a real export, so
// this deliberately over-requests (5000 rows) and the next function
// filters out anything past the real data — UNVERIFIED against a real
// oversized readRange call, see this tab's info note.
msg.params = { range: 'A1:Q5000', sheet: 'Sheet1' };
return msg;

// Output shape confirmed via body_comp_xlsx_test.json: array of arrays,
// row 0 is headers, every value is a string regardless of column type
// (explicit parseFloat/parseInt needed — nothing arrives pre-typed).
// Column order (A-Q, confirmed from PLAN.md §14's table against the
// same range already proven correct): 0 Measure Time, 1 Weight(lb),
// 2 Body Fat%, 3 BMI, 4 Skeletal Muscle%, 5 Muscle Mass(lb),
// 6 Protein%, 7 BMR(kcal), 8 Fat-free Body Weight(lb),
// 9 Subcutaneous Fat%, 10 Visceral Fat, 11 Body Water%, 12 Bone Mass(lb),
// 13 Metabolic Age, 14 Body Type (DROPPED — Ward's call, "their
// analytics, not what we will build"), 15 Device MAC, 16 Device Name.
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const dataRows = rows.slice(1); // skip header row
const num = v => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };

dataRows.forEach(r => {
    if (!r || !r[0]) return; // trailing empty row from the oversized range request
    const measureTime = String(r[0]).trim();
    const ts = new Date(measureTime);
    if (isNaN(ts.getTime())) return; // not a real data row
    msg.all_rows.push({
        measure_time: measureTime,
        ts_ms: ts.getTime(),
        date: ts.toISOString().slice(0, 10),
        weight_lb: num(r[1]),
        body_fat_pct: num(r[2]),
        bmi: num(r[3]),
        skeletal_muscle_pct: num(r[4]),
        muscle_mass_lb: num(r[5]),
        protein_pct: num(r[6]),
        bmr_kcal: num(r[7]),
        fat_free_body_weight_lb: num(r[8]),
        subcutaneous_fat_pct: num(r[9]),
        visceral_fat: num(r[10]),
        body_water_pct: num(r[11]),
        bone_mass_lb: num(r[12]),
        metabolic_age: num(r[13]),
        device_mac: r[15] ? String(r[15]).trim() : 'unknown',
        device_name: r[16] ? String(r[16]).trim() : 'unknown',
    });
});

msg.file_index += 1;
delete msg._doc; // avoid carrying the workbook object (circular refs) any further than needed
return msg;

// Rule 1 (PLAN.md §14): collapse to one reading per calendar day,
// keeping the latest-timestamped row — applies across ALL files read
// this run, not per-file, since a re-export can overlap a previous one.
const byDate = {};
(msg.all_rows || []).forEach(row => {
    const existing = byDate[row.date];
    if (!existing || row.ts_ms > existing.ts_ms) byDate[row.date] = row;
});
const chosen = Object.values(byDate);

function esc(s) { return String(s).replace(/([ ,=])/g, '\\$1'); }
const lines = [];
const weightPushes = [];
chosen.forEach(r => {
    const tsNs = r.ts_ms * 1000000;
    const fields = [];
    ['weight_lb','body_fat_pct','bmi','skeletal_muscle_pct','muscle_mass_lb',
     'protein_pct','bmr_kcal','fat_free_body_weight_lb','subcutaneous_fat_pct',
     'visceral_fat','body_water_pct','bone_mass_lb','metabolic_age'].forEach(f => {
        if (r[f] !== null && r[f] !== undefined) fields.push(f + '=' + r[f]);
    });
    if (fields.length) {
        lines.push('body_composition,device_mac=' + esc(r.device_mac) + ',device_name=' + esc(r.device_name) + ' ' + fields.join(',') + ' ' + tsNs);
    }
    // Rule 2 (weight_push.php's own job, not duplicated here): the
    // never-overwrite check happens server-side — this flow just sends
    // every collapsed day's weight and lets GoDaddy decide whether it's
    // a no-op.
    if (r.weight_lb !== null && r.weight_lb !== undefined) {
        weightPushes.push({ date: r.date, weight_lb: r.weight_lb });
    }
});

msg.influx_lines = lines;
msg.weight_pushes = weightPushes;
msg.record_count = chosen.length;

// Split/join (for the per-day weight-push loop below) doesn't reliably
// carry arbitrary top-level msg properties through every message in the
// group — stash what the tail of the flow needs in flow context instead
// of trusting that propagation.
flow.set('bci_secrets', msg.secrets);
flow.set('bci_job_started_at', msg.job_started_at);
return msg;

if (!msg.influx_lines.length) {
    return [null, msg];
}
msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_lines.join('\n');
return [msg, msg];

const secrets = flow.get('bci_secrets');
const day = msg.payload; // { date, weight_lb }
msg.url = secrets.godaddy_base_url + '/api/weight_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ date: day.date, weight_lb: day.weight_lb });
return msg;

const results = Array.isArray(msg.payload) ? msg.payload : [];
const written = results.filter(r => r && r.success && r.weight_written).length;
msg.weight_pushes_written = written;
msg.weight_pushes_total = results.length;
msg.job_started_at = flow.get('bci_job_started_at');
msg.secrets = flow.get('bci_secrets');

const files = msg.files || [];
if (!files.length) {
    return [null, msg];
}
const quoted = files.map(f => "'" + f.replace(/'/g, "'\\''") + "'").join(' ');
msg.payload = 'mkdir -p /share/lucius_body_comp_import/processed && mv ' + quoted + ' /share/lucius_body_comp_import/processed/';
return [msg, null];

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at || Date.now()).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=bodycomp_import,status=success record_count=' + (msg.record_count||0) + ',weight_pushes_written=' + (msg.weight_pushes_written||0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.ha_entities = [
    { entity_id: 'input_datetime.lucius_bodycomp_last_success', value: new Date().toISOString() },
    { entity_id: 'input_boolean.lucius_bodycomp_last_attempt_ok', value: 'on' },
    { entity_id: 'input_datetime.lucius_bodycomp_last_attempt', value: new Date().toISOString() }
];
if (!msg.secrets) msg.secrets = flow.get('bci_secrets');
return msg;

const nowNs = Date.now() * 1000000;
const detail = (node.error ? 'exceljs read/readRange failed' : 'unknown').replace(/([ ,="])/g, '\\$1');
msg.secrets = flow.get('bci_secrets');
msg.job_started_at = flow.get('bci_job_started_at');
msg.influx_finish_point = 'sync_job_runs,job_name=bodycomp_import,status=failed,failure_code=xlsx_parse_error detail="' + detail + '" ' + nowNs;
msg.ha_entities = [
    { entity_id: 'input_boolean.lucius_bodycomp_last_attempt_ok', value: 'off' },
    { entity_id: 'input_datetime.lucius_bodycomp_last_attempt', value: new Date().toISOString() },
    { entity_id: 'input_text.lucius_bodycomp_last_error', value: 'xlsx_parse_error: could not read/parse an .xlsx file in the watched folder' }
];
node.warn('Body Composition Import failed: could not read/parse an xlsx file');
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

// Same fix as the other two flows — setting a helper entity is a
// service call, not a direct state write. See godaddy_pull_flow.json's
// equivalent node for the full explanation.
function buildServiceCall(entity_id, value) {
    const domain = entity_id.split('.')[0];
    if (domain === 'input_boolean') {
        return { domain, service: value === 'on' ? 'turn_on' : 'turn_off', target: { entity_id }, data: {} };
    }
    if (domain === 'input_text') {
        return { domain, service: 'set_value', target: { entity_id }, data: { value: String(value) } };
    }
    if (domain === 'input_datetime') {
        return { domain, service: 'set_datetime', target: { entity_id }, data: { datetime: value } };
    }
    node.warn('No known service mapping for entity domain: ' + domain);
    return null;
}
return (msg.ha_entities || []).map(e => {
    const call = buildServiceCall(e.entity_id, e.value);
    if (!call) return null;
    return { domain: call.domain, service: call.service, target: call.target, payload: call.data };
}).filter(Boolean);
